 import AppLayout from '@/layouts/AppLayout.vue';
 import { guess, start } from '@/routes/rooms';
 import {
     MAX_GUESSES,
     WORD_LENGTH,
     type BoardRow,
     type LetterStatus,
 } from '@/types/game';

